                }
                "water" -> {
                    val cx = width / 2f
                    val cy = height / 2f
                    val r = minOf(width, height) / 2.5f
                    val waterFill = Paint().apply {
                        style = Paint.Style.STROKE
                        strokeWidth = dp(2f)
                        isAntiAlias = true
                        color = ColorUtils.setAlphaComponent(drawInk, 120)
                    }
                    canvas.drawCircle(cx, cy, r, waterFill)
                    canvas.drawCircle(cx, cy, r * 0.6f, waterFill.apply { strokeWidth = dp(1f); color = ColorUtils.setAlphaComponent(drawInk, 80) })
                }
            }
